htmx.registerExtension("hx-live-sse-collect",{init(e){document.addEventListener("htmx:sse:before:message",t=>{const s=t.target,r=t.detail.message;if(s.hasAttribute("hx-live-sse-collect")&&!r.event){t.preventDefault();try{const t=e.HCON.parse(r.data),a=htmx.live.q(s).local.data,i=Object.keys(t).map(e=>[e,a[e]]),c=Object.fromEntries(i),n=e.HCON.merge(t,c);Object.assign(a,n)}catch(r){e.triggerHtmxEvent(s,"htmx:sse:error",{...t.detail,error:r})}}})}});